                Util + "pixfmt.h",
                Util + "rational.h",
                Util + "samplefmt.h",
                Util + "time.h",
                Util + "version.h",
            ],
            [],
            [],
            []
        ),
        Library(
            "avcodec",
            "LibAVCodec",
            [
                "avcodec.h",
                "bsf.h",
                "codec.h",
                "codec_desc.h",
                "codec_id.h",
                "codec_par.h",
                "defs.h",
                "packet.h",
