    // hwcontext_vulkan.h embeds Vulkan values (enums and VkPhysicalDeviceFeatures2 by value), which are
    // generated from the pinned Vulkan-Headers, restricted to the declarations
    // the context structs use. Vulkan handles stay opaque: on the 64-bit targets these bindings support,
    // dispatchable and non-dispatchable handles alike are pointers to incomplete structs.
    private static Pass VulkanContext() =>
        new(
            "hw_vulkan",
            "avutil",
            "LibAVUtil",
            Host.Windows,
            ["libavutil/hwcontext_vulkan.h"],
            ["ffmpeg:libavutil/hwcontext_vulkan.h", "vulkan:vulkan/vulkan_core.h"],
            ["vulkan"],
            [
                "VkInstance_T=void",
                "VkPhysicalDevice_T=void",
                "VkDevice_T=void",
                "VkImage_T=void",
                "VkSemaphore_T=void",
                "VkDeviceMemory_T=void",
                "VkAllocationCallbacks=void",
            ],
            []
        )
        {
            DeclarationFilter =
            [
                "AV*",
                "av_*",
                "VkPhysicalDeviceFeatures",
                "VkPhysicalDeviceFeatures2",
                "VkStructureType",
                "VkFormat",
                "VkImageTiling",
                "VkImageLayout",
                "VkQueueFlagBits",
                "VkMemoryPropertyFlagBits",
                "VkImageUsageFlagBits",
                "VkVideoCodecOperationFlagBitsKHR",
                // Identifying which GPU a Vulkan device is (its LUID and UUID).
                "VkPhysicalDeviceProperties2",
                "VkPhysicalDeviceProperties",
                "VkPhysicalDeviceLimits",
                "VkPhysicalDeviceSparseProperties",
                "VkPhysicalDeviceType",
                "VkPhysicalDeviceIDProperties",
            ],
        };

    private static Pass HwContext(
        string name,
        string header,
        string[] includeRoots,
        string[]? remaps = null,
        string? prelude = null
    ) =>
        new(
            name,
            "avutil",
            "LibAVUtil",
            Host.Windows,
            [.. (prelude is null ? [] : new[] { prelude }), $"libavutil/{header}"],
            [$"ffmpeg:libavutil/{header}"],
            includeRoots,
            remaps ?? [],
            []
        );

    private static Pass Library(
        string library,
        string className,
        string[] headers,
        string[]? remaps = null
    ) =>
        new(
            library,
            library,
            className,
            Host.Windows,
            [.. headers.Select(h => $"lib{library}/{h}")],
            [.. headers.Select(h => $"ffmpeg:lib{library}/{h}")],
            [],
            remaps ?? [],
            []
        );

    // Diagnostics that are expected on every run and carry no information: function-like macros
    // (hand-written where needed) and GCC attributes on inline functions.
    public static bool IsAllowedDiagnostic(string diagnostic) =>
        diagnostic.Contains("Function like macro definition", StringComparison.Ordinal)
        || diagnostic.Contains("Unsupported attribute", StringComparison.Ordinal);
}

internal partial class Program
{
    [GeneratedRegex(@"public (?:unsafe )?partial struct (\w+)\s*\{\s*\}")]
    private static partial Regex OpaqueStruct();

    // One generated test class, top-level or nested, from its summary line to the brace that closes it
    // at the same indentation.
    [GeneratedRegex(
        @"^(?<indent>[ ]*)/// <summary>Provides validation of the <see cref=""(?<name>\w+)"" /> struct\.</summary>\r?\n.*?^\k<indent>\}\r?\n\r?\n?",
        RegexOptions.Multiline | RegexOptions.Singleline
    )]
    private static partial Regex TestClass();
}
